const ui = PlatformUI, esc = ui.escape, api = OutboundGroups;
let keyword = '', tenantId = '', page = 1, listContext = '', editor = null;
const command = (method, ...args) => esc(`OutboundGroupManagement.${method}(${args.map(v => JSON.stringify(v)).join(',')})`);

function members(id, key) {
  if (!valid(key)) return denied();
  const g = api.get(id);
  if (!g) return denied();
  const used = api.references(id).filter(t => t.alictiTaskControlPending || !['已完成', '已终止', '已结束', '已删除'].includes(t.status));
  if (used.length) return showToast('请先结束或删除关联任务后维护成员：' + used.map(t => t.name).join('、'), 'warning');

  editor = { kind: 'members', id, context: api.contextKey(), revision: api.revision() };
  const candidates = api.candidates(g.tenantId, g.enterpriseId);
  const ids = new Set(candidates.map(a => a.contactCenterIdentityId));
  const unavailable = g.memberIdentityIds.filter(mid => !ids.has(mid));

  ui.openLayer('outbound-group-edit', `

  ${unavailable.length ? ui.alert('warning', '存在不可用成员', '本次保存将自动移除已停用或无法找到的坐席成员。') : ''}
  <p class="field-hint">勾选加入，取消勾选移出。每位坐席只能属于一个外呼组，选择其他组成员会将其移入当前组。</p>
  <div class="obg-member-list" style="max-height:360px;overflow-y:auto;display:grid;grid-template-columns:repeat(auto-fill,minmax(260px,1fr));gap:10px;padding:8px 0;">
    ${candidates.map(a => {
      const isCurrent = g.memberIdentityIds.includes(a.contactCenterIdentityId);
      const inOther = a.assignedGroupId && a.assignedGroupId !== g.outboundGroupId;
      return `
      <label class="obg-member" style="display:flex;align-items:center;gap:8px;padding:10px;border:1px solid #e5e7eb;border-radius:6px;background:${isCurrent ? '#f0fdf4' : '#fff'};cursor:pointer;">
        <input type="checkbox" name="obg-member" value="${esc(a.contactCenterIdentityId)}" ${isCurrent ? 'checked' : ''}>
        <span style="flex:1;">
          <strong>${esc(a.userName)}</strong>
          <small style="color:#6b7280;display:block;">工号: ${esc(a.cno)}</small>
          ${inOther ? `<small style="color:#f59e0b;display:block;">[当前在: ${esc(a.assignedGroupName)}]</small>` : ''}
        </span>
      </label>`;
    }).join('') || ui.empty('当前租户暂无已启用坐席')}
  </div>
</div>
<div class="layer-footer">
  <button class="btn" onclick="PlatformUI.closeLayer('outbound-group-edit')">取消</button>
  <button class="btn btn-primary" onclick="OutboundGroupManagement.save()">保存成员</button>
</div>`, 'wide');

function save() {
  const e = editor;
  if (!e || !valid(e.context)) return denied();

  let result;
  if (e.kind === 'create') {
    const tenantSelect = document.getElementById('obg-tenant');
    const tenantVal = tenantSelect ? (tenantSelect.value || AppState.get().tenantId) : AppState.get().tenantId;
    result = api.create({
      name: document.getElementById('obg-name')?.value,
      gno: document.getElementById('obg-gno')?.value,
      comment: document.getElementById('obg-comment')?.value,
      tenantId: tenantVal
    }, e.context, e.revision);
  } else if (e.kind === 'edit') {
    result = api.update(e.id, {
      name: document.getElementById('obg-name')?.value,
      comment: document.getElementById('obg-comment')?.value
    }, e.context, e.revision);
  } else {
    const checkedIds = [...document.querySelectorAll('[name="obg-member"]:checked')].map(n => n.value);
    result = api.setMembers(e.id, checkedIds, e.context, e.revision);
  }

window.OutboundGroups = {
  forTask, choices, isGroup, taskSource, references, resolve, fields, canReceive, executionError,
  contextKey, canAccess, canManage, list, get, create, update, deleteGroup, setMembers,
  assignAgent, unassignAgent, listAssignedAgent, queryAgentGroup, candidates, tenantOptions,
  generateGno, revision, refresh, storageError: () => errorMessage
};

function setMembers(outboundGroupIdOrGno, memberIdentityIds, expectedContext, expectedRevision) {
  if (!validText(outboundGroupIdOrGno)) return failure('请选择要维护的外呼组');
  return transact(expectedContext, expectedRevision, next => {
    const group = next.groups.find(g => (g.outboundGroupId === outboundGroupIdOrGno || g.gno === outboundGroupIdOrGno) && inScope(g));
    if (!group || !inScope(group)) return failure('当前工作范围内找不到该外呼组');
    const used = references(group.outboundGroupId).filter(t => !['已完成', '已终止', '已结束', '已删除'].includes(t.status) || t.alictiTaskControlPending);
    if (used.length) return failure('请先结束或删除关联任务后维护成员：' + used.map(t => t.name).join('、'));

    const members = normalizeMembers(Array.isArray(memberIdentityIds) ? memberIdentityIds : [], group.tenantId, group.enterpriseId);
    if (!members.ok) return members;

    if (group.memberIdentityIds.length === members.value.length && group.memberIdentityIds.every((id, i) => id === members.value[i])) {
      return { unchanged: true };
    }

    const moved = moveMembersToGroup(next.groups, group, members.value);
    const msg = moved > 0 ? `外呼组成员已更新（${moved} 位坐席已自动从原外呼组移入）` : '外呼组成员已更新';
    return { message: msg, group };
  });
}

function contextKey() {
  const app = window.AppState, state = app?.get?.() || {}, access = app?.effectiveAccess?.() || {};
  return JSON.stringify([state.accountId || '', state.sessionId || '', app?.isSuper?.() ? 'SUPER_ADMIN' : access.roleCode || '', state.activeDomain || '', state.enterpriseId || '', state.tenantId || '']);
}
function canAccess() {
  const app = window.AppState, state = app?.get?.() || {}, access = app?.effectiveAccess?.() || {};
  return !!(state.accountId && state.sessionId && validText(state.enterpriseId) && app?.isReady?.() && access.valid &&
    state.activeDomain === 'CLOUD_CONTACT_CENTER' && app?.hasCapability?.('CLOUD_CONTACT_CENTER') && app?.canMenu?.('agents.manage') && (app.isSuper() || access.roleCode === 'ADMIN'));
}
function inScope(group) {
  if (!group) return false;
  const app = window.AppState, state = app.get();
  return group.enterpriseId === state.enterpriseId && app.authorizeObject('', group);
}
function canManage(group) { return canAccess() && inScope(group); }

function normalizeMembers(ids, tenantId, enterpriseId) {
  if (!Array.isArray(ids) || ids.length > 1000 || ids.some(id => !validText(id)) || new Set(ids).size !== ids.length) return failure('请选择有效且不重复的成员');
  for (const id of ids) {
    const agent = currentAgents().find(a => a.contactCenterIdentityId === id);
    if (!agent || agent.tenantId !== tenantId || agent.enterpriseId !== enterpriseId || agent.lifecycleStatus !== '已启用' || !AliCtiFields.validExistingCno(agent.cno) ||
      currentAgents().filter(a => a.enterpriseId === enterpriseId && a.cno === agent.cno).length !== 1) {
      return failure('成员必须为当前租户、当前企业内已启用的坐席');
    }
  }
  return { ok: true, value: clone(ids) };
