    let result;
    if (e.kind === 'create') {
      const tenantSelect = document.getElementById('obg-tenant');
      const tenantVal = tenantSelect ? (tenantSelect.value || AppState.get().tenantId) : AppState.get().tenantId;
      result = api.create({
        name: document.getElementById('obg-name')?.value,
